import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&w.startsWith('transportaction_'))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text)}catch{}walk(v);return v}
const actions=['start','continue','stop','play-selection','scrub','tap-tempo','nudge-up','nudge-down','re-enable-automation','trigger-session-record','force-link-beat-time','stop-all-clips','back-to-arrangement','jump-by','jump-in-running-clip'];
const args=action=>({action,...(['scrub','force-link-beat-time'].includes(action)?{beatTime:3}:{}),...(['jump-by','jump-in-running-clip'].includes(action)?{beats:-2}:{}),...(action==='jump-in-running-clip'?{trackRef:'track:track-1'}:{})});
const rows=[];for(const action of actions){const valid=args(action);const cases=[valid,{...valid,extra:true}];for(const key of ['action','beatTime','beats','trackRef']){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},true,false,'',0,1,-1,1000001,'missing','x'.repeat(257)])cases.push({...valid,[key]:value})}for(const p of cases){const host=new McpHost(new DeterministicLiveSimulator());rows.push({args:p,result:clean(await host.liveTransportActionPreviewAsync(1,p))})}}
for(const p of [null,[],{},false,0,'x']){const host=new McpHost(new DeterministicLiveSimulator());rows.push({args:p,result:clean(await host.liveTransportActionPreviewAsync(1,p))})}
const workflows=[];for(const action of actions)for(const scenario of ['normal','expire','epoch','identity-edit','playback-edit','track-edit','apply-before','apply-after','apply-refusal','apply-no-effect','apply-current-read','apply-preabort']){
const sim=new DeterministicLiveSimulator(),calls=[],cache=new Map();let fault='',fired=false,afterInvoke=false;
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null}
function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='apply-current-read'||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure')}}
function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return structuredClone(cache.get(key));if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure')}const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,structuredClone(result));afterInvoke=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure')}if(!fired&&['apply-invalid-identity','apply-invalid-fingerprint','apply-no-fingerprint'].includes(fault)){fired=true;result[fault.endsWith('identity')?'objectIdentity':'createdFingerprint']='';if(fault==='apply-no-fingerprint')delete result.createdFingerprint}return result}
const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async c=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};

const host=new McpHost(adapter),results=[],states=[];const preview=await host.liveTransportActionPreviewAsync(1,args(action));results.push(clean(preview));const txid=JSON.parse(preview.result.content[0].text).transactionId;
if(txid){const record=host.clipLifecycleTransactions.get(txid);if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity-edit')sim.state.set.objectIdentity='other';if(scenario==='track-edit')sim.state.tracks[0].objectIdentity='other';if(scenario==='playback-edit')sim.state.playback.transport.position=44;if(scenario.startsWith('apply-'))fault=scenario;
for(const key of ['apply-key','other-key','apply-key']){const controller=new AbortController();if(scenario==='apply-preabort')controller.abort();results.push(clean(await host.liveTransportActionApplyAsync(results.length+1,{transactionId:txid,confirmation:'apply',idempotencyKey:key},controller.signal)));states.push(clean(record));}}
workflows.push({action,scenario,results,states,calls,state:sim.state});}
fs.writeFileSync(new URL('host-transport-action-oracle.json',import.meta.url),JSON.stringify({rows,workflows}));console.log({rows:rows.length,workflows:workflows.length});
